    "ctxApiRefBody": "ctx.ref(val)              — создание реактивной переменной\nctx.computed(fn)          — создание вычисляемого свойства\nctx.watch(src, cb)        — отслеживание изменений\nctx.onMounted(fn)         — при монтировании компонента\nctx.onUnmounted(fn)       — при размонтировании компонента\n\nctx.data.client           — данные учётной записи пользователя (реактивно)\nctx.data.token            — текущий token (реактивно)\nctx.data.isDark           — тёмный режим (реактивно)\n\nctx.api.get(path, query)  — GET-запрос\nctx.api.post(path, body)  — POST-запрос\nctx.api.put(path, body)   — PUT-запрос\nctx.api.delete(path)      — DELETE-запрос\n\nctx.formatBytes(bytes)    — форматирование размера файла\nctx.formatDate(date)      — форматирование даты\nctx.copyText(text)        — копирование в буфер обмена\nctx.elMessage             — сообщения Element Plus\nctx.config                — конфигурация портала (PORTAL_CONFIG)\nctx.moduleId              — ID текущего модуля\nctx.moduleTitle           — заголовок текущего модуля",
